  box-shadow: 0 0 0 4px var(--spherica-color-primary-ui-system-focus-out)
}

input[type=radio]+label::before {
  height: 24px;
  width: 24px;
  content: "";
  min-width: 24px;
  border-radius: 50%;
  display: inline-block;
  border: 1px solid var(--inputradio-border-color, #121212);
  position: relative;
  top: 5px;
  margin-right: 8px;
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
  background-color: var(--inputradio-background-color, #fff)
}

input[type=radio]:checked+label::before {
  background-color: var(--inputradio-fill-color, #004481);
  -webkit-box-shadow: inset 0 0 0 4px var(--inputradio-background-color, #fff);
  box-shadow: inset 0 0 0 4px var(--inputradio-background-color, #fff)
}

